alter table public.tracker_profiles add column if not exists banner_path text constraint tracker_profiles_banner_path_check check (banner_path is null or (char_length(banner_path)<=200 and (banner_path like id::text || '/%' or banner_path in ('theme:fire-emblem-heroes','theme:midgard','theme:nifl','theme:muspell','theme:hel','theme:ljosalfheimr','theme:dokkalfheimr','theme:nidavellir','theme:jotunheimr','theme:vanaheimr','theme:asgardr'))));
do $migration$ declare definition text; begin definition:=pg_get_functiondef('public.get_public_tracker_profile(uuid)'::regprocedure); if position($needle$'banner_path'$needle$ in definition)=0 then definition:=replace(definition,$old$'avatar_path',p.avatar_path,$old$,$new$'avatar_path',p.avatar_path,'banner_path',p.banner_path,$new$); execute definition; end if; end $migration$;
